"""Keep the Trading chart's exit level generated by the tool, never hand-edited."""

import json
import re
from pathlib import Path

import yaml

from butterfly_guy.core.config import ProfitManagementSettings
from tools.update_grafana_exit_trigger import exit_trigger_sql, regime_annotation, update_dashboard

ROOT = Path(__file__).resolve().parents[1]
DASHBOARD = ROOT / "infra/grafana/dashboards/butterfly_trading.json"


def _policies() -> dict[str, ProfitManagementSettings]:
    return {
        asset: ProfitManagementSettings.model_validate(
            yaml.safe_load((ROOT / "configs" / name).read_text())["profit_management"]
        )
        for asset, name in (
            ("SPX", "config.yaml"), ("NDX", "config_ndx.yaml"), ("XSP", "config_xsp.yaml")
        )
    }


def _value_panel_sql() -> str:
    panel = next(p for p in json.loads(DASHBOARD.read_text())["panels"] if p["id"] == 3)
    return panel["targets"][0]["rawSql"]


def _deployed_policies() -> dict[str, ProfitManagementSettings]:
    # The chart embeds the running bots' policies, which can differ from the checked-in
    # configs (XSP runs from a release snapshot), so read them back from the chart.
    return {
        asset: ProfitManagementSettings.model_validate(json.loads(settings.replace("''", "'")))
        for asset, settings in re.findall(
            r"\('(SPX|NDX|XSP)', '(.*?)'::jsonb\)", _value_panel_sql()
        )
    }


def _regimes(annotations: list[dict]) -> list[dict]:
    return [a for a in annotations if a["name"] == "Drawdown regimes"]


def test_chart_exit_level_is_tool_generated_for_the_session_on_screen() -> None:
    policies = _deployed_policies()
    sql = _value_panel_sql()

    assert set(policies) == {"SPX", "NDX", "XSP"}
    assert sql == exit_trigger_sql(policies)
    # The DB runs in UTC: CURRENT_DATE rolls to tomorrow at 17:00 PT.
    assert "CURRENT_DATE" not in sql
    assert "t.trade_date = '$session_date'::date" in sql


def test_refresh_changes_only_value_panel_and_accepts_deployed_policies(tmp_path: Path) -> None:
    original = json.loads(DASHBOARD.read_text())
    path = tmp_path / "dashboard.json"
    path.write_text(DASHBOARD.read_text())
    policies = _policies()
    policies["XSP"] = policies["XSP"].model_copy(update={"strategy": "profitprotector"})

    update_dashboard(path, policies)
    updated = json.loads(path.read_text())
    for before, after in zip(original["panels"], updated["panels"], strict=True):
        if before["id"] != 3:
            assert before == after
        else:
            assert after["targets"][0]["rawSql"] == exit_trigger_sql(policies)
    assert {k: v for k, v in original.items() if k not in {"panels", "annotations"}} == {
        k: v for k, v in updated.items() if k not in {"panels", "annotations"}
    }
    assert _regimes(updated["annotations"]["list"]) == [regime_annotation(policies)]
    assert [a for a in updated["annotations"]["list"] if a["name"] != "Drawdown regimes"] == [
        a for a in original["annotations"]["list"] if a["name"] != "Drawdown regimes"
    ]
    first = path.read_text()
    update_dashboard(path, policies)
    assert path.read_text() == first


def test_regime_markers_match_configs_and_only_appear_on_value_chart() -> None:
    annotations = _regimes(json.loads(DASHBOARD.read_text())["annotations"]["list"])
    assert annotations == [regime_annotation(_deployed_policies())]
    marker = annotations[0]
    assert marker["enable"] is True
    assert marker["filter"] == {"exclude": False, "ids": [3]}
    assert marker["datasource"]["uid"] == "${strategy_datasource}"
    assert "CURRENT_TIMESTAMP" not in marker["target"]["rawSql"]

    # Regime starts and percentages must come from the supplied runtime configs.
    policies = _policies()
    policies["SPX"].regimes["late_morning"].start_minutes_after_open = 90
    policies["SPX"].regimes["late_morning"].drawdown_threshold = 0.7
    sql = regime_annotation(policies)["target"]["rawSql"]
    assert "('SPX', 90, 'Late morning', 70)" in sql
    assert "AT TIME ZONE 'America/New_York'" in sql
    assert "'$session_date'::date" in sql
    assert "$__timeFilter(time)" in sql


def test_refresh_preserves_other_annotations(tmp_path: Path) -> None:
    dashboard = json.loads(DASHBOARD.read_text())
    other = {"name": "Unrelated", "enable": True}
    dashboard["annotations"]["list"].append(other)
    kept = [a for a in dashboard["annotations"]["list"] if a["name"] != "Drawdown regimes"]
    path = tmp_path / "dashboard.json"
    path.write_text(json.dumps(dashboard, indent=2))

    update_dashboard(path, _policies())

    assert json.loads(path.read_text())["annotations"]["list"] == [
        *kept, regime_annotation(_policies())
    ]
